declare(strict_types=1);

function render_app(string $view): void
{
    page_header($view);
    match ($view) {
        'student' => view_student(),
        'learn' => view_learn(),
        'competencies' => view_competencies(),
        'rewards' => view_rewards(),
        'join' => view_join_course(),
        'teacher' => view_teacher(),
        'student-detail' => view_student_detail(),
        'students' => view_students(),
        'library' => view_library(),
        'page-edit' => view_page_edit(),
        'pathway' => view_pathway(),
        'outbox' => view_outbox(),
        'profile' => view_profile(),
        'admin' => view_admin(),
        default => null,
    };
    page_footer($view);
}

