function render_password_reset(string $token): void
{
    $token=trim($token);
    $account=preg_match('/^[A-Za-z0-9_-]{22}$/',$token)?password_reset_user(db(),hash('sha256',$token)):null;
    if(!$account){flash('Ce lien de réinitialisation est invalide ou expiré.','error');redirect('recover');}
    $language=normalize_language((string)($account['language']??''));if($language!==null)use_language($language);
    $flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
    ?><!doctype html><html lang="<?=e(current_language())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#29273b"><meta name="apple-mobile-web-app-capable" content="yes"><title><?=e(t('Nouveau mot de passe'))?> · <?=e(APP_NAME)?></title><link rel="manifest" href="manifest.webmanifest"><link rel="icon" href="assets/icon.svg"><link rel="apple-touch-icon" sizes="180x180" href="assets/apple-touch-icon.png"><link rel="stylesheet" href="assets/vendor/bootstrap/bootstrap.min.css"><link rel="stylesheet" href="assets/vendor/bootstrap-icons/bootstrap-icons.min.css"><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><main class="container-fluid p-0 min-vh-100"><div class="row g-0 min-vh-100"><section class="login-intro col-lg-5 d-flex flex-column justify-content-between"><a class="brand text-white" href="."><span class="brand-mark bg-white text-dark">ii</span><span>liike</span></a><div><p class="eyebrow"><?=e(t('Compte enseignant'))?></p><h1><?=e(t('Choisir un nouveau mot de passe.'))?></h1></div></section><section class="login-card col-lg-7 d-flex align-items-center"><div class="w-100 mx-auto registration-form-wrap"><a class="back mb-3" href=".">← <?=e(t('Retour à la connexion'))?></a><?php if($flash): ?><div class="alert alert-danger"><?=e($flash['message'])?></div><?php endif; ?><h2><?=e(t('Nouveau mot de passe'))?></h2><p class="text-secondary"><?=e(t('Utilisez au moins 8 caractères.'))?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="reset_token" value="<?=e($token)?>"><div class="mb-3"><label class="form-label fw-semibold" for="reset-password"><?=e(t('Nouveau mot de passe'))?></label><input class="form-control form-control-lg" id="reset-password" type="password" name="new_password" required minlength="8" autocomplete="new-password"></div><div class="mb-3"><label class="form-label fw-se