      <nav class="desktop-nav nav nav-pills"><?php if($isTeacher): ?><a class="nav-link <?=in_array($view,['teacher','student-detail'])?'active':''?>" href="<?=route('teacher')?>"><?=e(t('Suivi'))?></a><a class="nav-link <?=$view==='students'?'active':''?>" href="<?=route('students')?>"><?=e(t('Élèves'))?></a><a class="nav-link <?=$view==='library'?'active':''?>" href="<?=route('library')?>"><?=e(t('Bibliothèque'))?></a><a class="nav-link <?=$view==='pathway'?'active':''?>" href="<?=route('pathway')?>"><?=e(t('Parcours'))?></a><?php else: ?><a class="nav-link <?=$view==='student'?'active':''?>" href="<?=route('student')?>"><?=e(t('Aujourd’hui'))?></a><a class="nav-link <?=$view==='competencies'?'active':''?>" href="<?=route('competencies')?>"><?=e(t('Acquis'))?></a><a class="nav-link <?=$view==='rewards'?'active':''?>" href="<?=route('rewards')?>"><?=e(t('Encouragements'))?></a><?php endif; ?></nav>
