    if($view==='page-edit'&&(int)($_GET['id']??0)>0){?><div class="transfer-panel compact"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="export_page"><input type="hidden" name="page_id" value="<?=(int)$_GET['id']?>"><button class="btn btn-outline-secondary"><i class="bi bi-download"></i> <?=e(t('Exporter cette page en JSON'))?></button></form></div><?php return;}
}

