function student_context(): array
{
    $user=require_actor();
    $courses=all("SELECT c.*,e.id AS enrollment_id FROM courses c JOIN enrollments e ON e.course_id=c.id WHERE e.student_id=? AND e.status='active' AND c.archived=0 ORDER BY c.title",[$user['id']]);
    $wanted=(int)($_GET['course']??($courses[0]['id']??0));
    $course=null; foreach($courses as $c) if((int)$c['id']===$wanted)$course=$c;
    $course??=$courses[0]??null;
    return [$courses,$course];
}

function course_switcher(array $courses, ?array $course, string $view): void
{
    if(!$course)return; ?><div class="course-switch"><span class="course-dot" style="--course:<?=e($course['accent'])?>"></span><select aria-label="<?=e(t('Changer de cours'))?>" onchange="location.href=this.value"><?php foreach($courses as $c): ?><option value="<?=route($view,['course'=>$c['id']])?>" <?=$c['id']===$course['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach; ?></select><?php if(count($courses)>1): ?><span class="course-switch-more" title="<?=e(t('Autres parcours disponibles'))?>" aria-hidden="true">+</span><?php endif; ?></div><?php
}

function view_join_course(): void
{
    $user=require_actor();
    if($user['role']!=='student'){?><div class="empty"><?=e(t('Seul un compte élève peut rejoindre un cours.'))?></div><?php return;}
    if(isset($_GET['reset']))unset($_SESSION['pending_join_course_code']);
    $code=trim((string)($_GET['code']??$_SESSION['pending_join_course_code']??''));
    $course=$code!==''?find_joinable_course(db(),$code):null;
    if($course)$_SESSION['pending_join_course_code']=$course['code'];
    elseif($code!=='')unset($_SESSION['pending_join_course_code']);
    $existing=$course?one('SELECT status FROM enrollments WHERE course_id=? AND student_id=?',[$course['id'],$user['id']]):null;
    ?><section class="page-heading"><p class="eyebrow"><?=e(t('Inscription autonome'))?></p><h1><?=e(t('Rejoindre un cours'))?></h1><p><?=e(t('Saisissez le code transmis par votre enseignant ou ouvrez directement son lien d’invitation.'))?></p></section><section class="settings-card join-course-card"><?php if($course): ?><div class="join-course-summary"><span class="course-dot" style="--course:<?=e($course['accent'])?>"></span><div><p class="eyebrow"><?=e(t('Cours trouvé'))?></p><h2><?=e($course['title'])?></h2><p><?=e(t('Enseignant : :name',['name'=>$course['teacher_name']]))?></p></div><strong><?=e($course['code'])?></strong></div><?php if(($existing['status']??'')==='active'): ?><div class="alert alert-success mb-0"><?=e(t('Vous êtes déjà inscrit·e à ce cours.'))?></div><a class="button primary mt-3" href="<?=route('student',['course'=>$course['id']])?>"><?=e(t('Ouvrir le cours'))?></a><?php elseif(($existing['status']??'')==='archived'): ?><div class="alert alert-warning mb-0"><?=e(t('Votre ancienne participation à ce cours est archivée. Contactez votre enseignant pour la réactiver.'))?></div><?php else: ?><form method="post" class="mt-4"><?=csrf_field()?><input type="hidden" name="action" value="join_course"><input type="hidden" name="course_code" value="<?=e($course['code'])?>"><button class="button primary full"><i class="bi bi-person-plus me-2"></i><?=e(t('Rejoindre ce cours'))?></button></form><?php endif; ?><a class="d-inline-block mt-3 text-secondary" href="<?=route('join',['reset'=>1])?>"><?=e(t('Utiliser un autre code'))?></a><?php else: ?><?php if($code!==''): ?><div class="alert alert-danger"><?=e(t('Ce code ne correspond à aucun cours disponible.'))?></div><?php endif; ?><form method="get"><input type="hidden" name="view" value="join"><label class="field"><span><?=e(t('Code du cours'))?></span><input class="form-control form-control-lg text-uppercase" name="code" required maxlength="64" autocapitalize="characters" autocomplete="off" placeholder="BIO-10A"></label><button class="button primary full mt-3"><?=e(t('Vérifier le code'))?></button></form><?php endif; ?></section><?php
}

function view_student(): void
{
    [$courses,$course]=student_context(); if(!$course){view_join_course();return;}
    $items=all("SELECT pi.*,p.title,p.summary,p.estimated_minutes,pr.student_level,pr.student_validated_at,pr.teacher_level,pr.teacher_validated_at
      FROM pathway_items pi JOIN pages p ON p.id=pi.page_id LEFT JOIN progress pr ON pr.pathway_item_id=pi.id AND pr.enrollment_id=? WHERE pi.course_id=?
      AND (pi.access_mode='all' OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=?))) ORDER BY pi.position",[$course['enrollment_id'],$course['id'],actor()['id']]);
    $studentDone=count(array_filter($items,fn($i)=>$i['student_validated_at'])); $confirmed=count(array_filter($items,fn($i)=>$i['teacher_validated_at'])); $total=count($items);
    $next=null; foreach($items as $i) if(!$i['student_validated_at']){$next=$i;break;} $next??=$items[array_key_last($items)]??null;
    $rewards=reward_summary((int)$course['enrollment_id']);
    ?><section class="student-hero"><div><?php course_switcher($courses,$course,'student'); ?><p class="eyebrow"><?=e(t('Bonjour :name', ['name'=>explode(' ',actor()['name'])[0]]))?> 👋</p><h1><?=e(t($studentDone===$total?'Parcours terminé !':'Prêt·e pour la suite ?'))?></h1><p><?=e($course['description'])?></p></div><a class="reward-pill" href="<?=route('rewards',['course'=>$course['id']])?>"><b>✦ <?=$rewards['total']?></b><span><?=e(t('points'))?></span></a></section>
    <section class="progress-card"><div class="progress-head"><div><span><?=e(t('Ton parcours'))?></span><b><?=e(t(':done sur :total étapes réalisées',['done'=>$studentDone,'total'=>$total]))?></b></div><strong><?= $total?round($studentDone/$total*100):0 ?>%</strong></div><div class="progress-track"><i style="width:<?=$total?$studentDone/$total*100:0?>%"></i></div><div class="progress-legend"><span>● <?=e(t(':count confirmées',['count'=>$confirmed]))?></span><span>○ <?=e(t(':count en attente',['count'=>$studentDone-$confirmed]))?></span></div></section>
    <?php if($next): [$due,$kind]=due_meta($next['deadline'],(bool)$next['student_validated_at']); ?><section><div class="section-title"><div><span class="eyebrow"><?=e(t('Prochaine étape'))?></span><h2><?=e($next['title'])?></h2></div><span class="due <?=$kind?>"><?=e($due)?></span></div><a class="next-card" href="<?=route('learn',['item'=>$next['id']])?>"><div class="next-visual"><span><?=e(t($next['is_evaluation']?'ÉVALUATION':'ÉTAPE :number',['number'=>$next['position']]))?></span><b><?= $next['is_evaluation']?'◆':'↗'?></b></div><div><p><?=e($next['summary'])?></p><span><?=e(t('Environ :minutes min',['minutes'=>$next['estimated_minutes']]))?></span><strong><?=e(t($next['student_validated_at']?'Revoir l’étape':'Commencer'))?> →</strong></div></a></section><?php endif; ?>
    <section><div class="section-title"><h2><?=e(t('Vue d’ensemble'))?></h2><a href="<?=route('competencies',['course'=>$course['id']])?>"><?=e(t('Voir mes acquis'))?></a></div><div class="timeline"><?php foreach($items as $item): [$due,$kind]=due_meta($item['deadline'],(bool)$item['student_validated_at']); ?><a href="<?=route('learn',['item'=>$item['id']])?>" class="timeline-item <?= $item['teacher_validated_at']?'confirmed':($item['student_validated_at']?'waiting':'')?>"><span class="timeline-state"><?= $item['teacher_validated_at']?'✓':($item['student_validated_at']?'◷':$item['position'])?></span><div><b><?=e($item['title'])?></b><small><?=e($due)?><?= $item['is_evaluation']?' · '.e(t('Évaluation')):''?></small></div><?php if($item['teacher_validated_at']): ?><em><?=e(t('Niv.'))?> <?=$item['teacher_level']?></em><?php endif; ?></a><?php endforeach; ?></div></section><?php
}

function view_learn(): void
{
    $item=one("SELECT pi.*,p.title,p.summary,p.estimated_minutes,c.title AS course_title,c.id AS course_id,e.id AS enrollment_id,pr.student_level,pr.student_note,pr.student_validated_at,pr.teacher_level,pr.teacher_note,pr.teacher_validated_at
      FROM pathway_items pi JOIN pages p ON p.id=pi.page_id JOIN courses c ON c.id=pi.course_id JOIN enrollments e ON e.course_id=c.id AND e.student_id=? AND e.status='active' LEFT JOIN progress pr ON pr.pathway_item_id=pi.id AND pr.enrollment_id=e.id WHERE pi.id=?
      AND (pi.access_mode='all' OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=?)))",[actor()['id'],(int)($_GET['item']??0),actor()['id']]);
    if(!$item){?><div class="empty"><?=e(t('Cette étape n’est pas disponible.'))?></div><?php return;}
    $blocks=all('SELECT * FROM page_blocks WHERE page_id=? ORDER BY position',[$item['page_id']]);
    $skills=all('SELECT s.* FROM course_skills s JOIN item_skills l ON l.skill_id=s.id WHERE l.pathway_item_id=?',[$item['id']]);
    $objectives=page_objectives(db(),(int)$item['page_id']);
    $prev=one("SELECT id FROM pathway_items pi WHERE course_id=? AND position<? AND (pi.access_mode='all' OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=?))) ORDER BY position DESC LIMIT 1",[$item['course_id'],$item['position'],actor()['id']]); $next=one("SELECT id FROM pathway_items pi WHERE course_id=? AND position>? AND (pi.access_mode='all' OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=?))) ORDER BY position LIMIT 1",[$item['course_id'],$item['position'],actor()['id']]);
    ?><span hidden data-learning-tracker data-item-id="<?=$item['id']?>"></span><?php
    ?><div class="reader-top"><a class="back" href="<?=route('student',['course'=>$item['course_id']])?>">← <?=e(t('Parcours'))?></a><span><?=e(t('Étape :number',['number'=>$item['position']]))?> · <?=e($item['course_title'])?></span></div><article class="reader"><header><div class="reader-meta"><span><?=e(t($item['is_evaluation']?'◆ Évaluation':'Étape :number',['number'=>$item['position']]))?></span><span>◷ <?=$item['estimated_minutes']?> min</span><?php if($item['deadline']): ?><span><?=e(t('Échéance'))?> <?=date_fr($item['deadline'])?></span><?php endif; ?></div><h1><?=e($item['title'])?></h1><p><?=e($item['summary'])?></p><?php if($skills||$objectives): ?><div class="chips"><?php foreach($skills as $s): ?><span class="chip skill"><?=e($s['code'])?> · <?=e($s['title'])?></span><?php endforeach; ?><?php foreach($objectives as $o): ?><span class="chip">◎ <?=e($o['title'])?></span><?php endforeach; ?></div><?php endif; ?></header>
    <?php foreach($blocks as $block): ?><section class="content-block type-<?=e($block['type'])?>"><?php if($block['type']==='markdown'): ?><?=Markdown::render($block['body'])?><?php elseif($block['type']==='image'): ?><figure><img src="<?=e($block['body'])?>" alt="<?=e($block['caption'])?>"><figcaption><?=e($block['caption'])?></figcaption></figure><?php elseif($block['type']==='file'): ?><a class="file-card" href="<?=e($block['body'])?>" download><span>↓</span><div><b><?=e($block['caption']?:basename($block['body']))?></b><small><?=e(t('Télécharger le fichier'))?></small></div></a><?php else: ?><div class="iframe-wrap"><iframe src="<?=e($block['body'])?>" title="<?=e($block['caption'])?>" loading="lazy" allowfullscreen></iframe></div><?php endif; ?></section><?php endforeach; ?>
    <?php if($item['teacher_validated_at']): ?><div class="validation-result confirmed"><span>✓</span><div><b><?=e(t('Confirmé au niveau :level · :label',['level'=>$item['teacher_level'],'label'=>t(LEVELS[(int)$item['teacher_level']]['label'])]))?></b><p><?=e($item['teacher_note']?:t('Cette étape est validée par votre enseignant.'))?></p></div></div><?php elseif($item['student_validated_at']): ?><div class="validation-result waiting"><span>◷</span><div><b><?=e(t('Envoyé à votre enseignant'))?></b><p><?=e(t('Auto-positionnement : niveau :level. Vous pouvez encore le modifier.',['level'=>$item['student_level']]))?></p></div></div><?php endif; ?>
    <section class="self-check"><span class="eyebrow"><?=e(t('Avant de continuer'))?></span><h2><?=e(t('Où en es-tu ?'))?></h2><p><?=e(t('Choisis le niveau qui te ressemble aujourd’hui. Il pourra évoluer.'))?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="student_validate"><input type="hidden" name="item_id" value="<?=$item['id']?>"><?=render_level_picker('level',$item['student_level']===null?null:(int)$item['student_level'])?><label class="field"><span><?=e(t('Un mot sur ton travail'))?> <em><?=e(t('facultatif'))?></em></span><textarea name="note" rows="3" placeholder="<?=e(t('Ce qui a été facile, difficile, ou ce dont tu es fier·e…'))?>"><?=e($item['student_note'])?></textarea></label><button class="button primary full"><?=e(t('Valider et envoyer'))?></button></form></section>
    <nav class="reader-nav"><?php if($prev): ?><a href="<?=route('learn',['item'=>$prev['id']])?>">← <?=e(t('Précédent'))?></a><?php else:?><span></span><?php endif; ?><?php if($next): ?><a href="<?=route('learn',['item'=>$next['id']])?>"><?=e(t('Suivant'))?> →</a><?php endif; ?></nav></article><?php
}

function view_competencies(): void
{
    [$courses,$course]=student_context(); if(!$course)return; $kind=($_GET['kind']??'skill')==='objective'?'objective':'skill'; $rows=framework_progress((int)$course['id'],(int)$course['enrollment_id'],$kind);
