    [$courses,$course]=student_context(); if(!$course)return; $r=reward_summary((int)$course['enrollment_id']);
    ?><section class="page-heading"><?php course_switcher($courses,$course,'rewards'); ?><p class="eyebrow"><?=e(t('Mes encouragements'))?></p><h1><?=e(t('Encouragements'))?></h1><p><?=e(t('Ils saluent ta manière d’apprendre. Tes compétences restent évaluées séparément.'))?></p></section><section class="reward-hero"><span>✦</span><div><strong><?=$r['total']?></strong><b><?=e(t('points cumulés'))?></b><small><?=e(t(':count encouragements reçus',['count'=>$r['count']]))?></small></div></section><div class="reward-types"><?php foreach($r['types'] as $type): ?><div style="--reward:<?=e($type['color'])?>"><span><?=e($type['icon'])?></span><b><?=e($type['name'])?></b><em><?=$type['points']?> pts</em></div><?php endforeach; ?></div><section><div class="section-title"><h2><?=e(t('Derniers encouragements'))?></h2></div><div class="reward-feed"><?php foreach($r['recent'] as $award): ?><article><span style="--reward:<?=e($award['color'])?>"><?=e($award['icon'])?></span><div><b><?=e($award['name'])?> · +<?=$award['points']?></b><p><?=e($award['message']?:$award['page_title'])?></p><small><?=date_fr($award['awarded_at'],true)?></small></div></article><?php endforeach; ?><?php if(!$r['recent']): ?><div class="empty"><?=e(t('Les encouragements de votre enseignant apparaîtront ici.'))?></div><?php endif; ?></div></section><?php
}

function teacher_context(): array
{
    $courses=all("SELECT c.*,(SELECT COUNT(*) FROM enrollments e JOIN users s ON s.id=e.student_id WHERE e.course_id=c.id AND e.status='active' AND s.account_status='active') AS student_count FROM courses c WHERE (c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?)) AND archived=0 ORDER BY title",[actor()['id'],actor()['id']]);
    $wanted=(int)($_GET['course']??($courses[0]['id']??0)); $course=null; foreach($courses as $c)if((int)$c['id']===$wanted)$course=$c; $course??=$courses[0]??null; return[$courses,$course];
}

function view_teacher(): void
{
    [$courses,$course]=teacher_context(); if(!$course)return;
    $students=all("SELECT e.id AS enrollment_id,u.*,COUNT(pi.id) AS total,SUM(CASE WHEN pr.student_validated_at IS NOT NULL THEN 1 ELSE 0 END) AS done,SUM(CASE WHEN pr.teacher_validated_at IS NOT NULL THEN 1 ELSE 0 END) AS confirmed,SUM(CASE WHEN pr.student_validated_at IS NOT NULL AND pr.teacher_validated_at IS NULL THEN 1 ELSE 0 END) AS waiting,COALESCE((SELECT SUM(points) FROM reward_awards ra WHERE ra.enrollment_id=e.id),0) AS points FROM enrollments e JOIN users u ON u.id=e.student_id LEFT JOIN pathway_items pi ON pi.course_id=e.course_id AND (pi.access_mode='all' OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=e.student_id))) LEFT JOIN progress pr ON pr.enrollment_id=e.id AND pr.pathway_item_id=pi.id WHERE e.course_id=? AND e.status='active' AND u.account_status='active' GROUP BY e.id ORDER BY u.name",[$course['id']]);
    $waiting=array_sum(array_column($students,'waiting'));
    ?><section class="teacher-heading"><div><h1><?=e(t('Tableau de bord'))?></h1><p><?=e(t('Voici où en est votre classe aujourd’hui.'))?></p></div><a class="button secondary" href="<?=route('outbox')?>">✉ <?=e(t('Notifications'))?></a></section><div class="course-tabs"><?php foreach($courses as $c): ?><a class="<?=$c['id']===$course['id']?'active':''?>" href="<?=route('teacher',['course'=>$c['id']])?>"><i style="--course:<?=e($c['accent'])?>"></i><?=e($c['title'])?><small><?=e(t(':count élèves',['count'=>$c['student_count']]))?></small></a><?php endforeach; ?></div><section class="metrics"><div><span><?=e(t('Progression moyenne'))?></span><b><?=count($students)?round(array_sum(array_map(fn($s)=>$s['total']?$s['done']/$s['total']*100:0,$students))/count($students)):0?>%</b></div><div class="attention"><span><?=e(t('À confirmer'))?></span><b><?=$waiting?></b></div><div><span><?=e(t('Prochaine évaluation'))?></span><b><?=e(date_fr(one("SELECT MIN(deadline) AS d FROM pathway_items WHERE course_id=? AND is_evaluation=1 AND deadline>=date('now')",[$course['id']])['d']??null))?></b></div></section><section><div class="section-title"><div><h2><?=e(t('Progression des élèves'))?></h2><p><?=e(t('Appuyez sur un élève pour ouvrir son suivi.'))?></p></div><a href="<?=route('pathway',['course'=>$course['id']])?>"><?=e(t('Organiser le parcours'))?> →</a></div><div class="student-table"><div class="table-head"><span><?=e(t('Élève'))?></span><span><?=e(t('Progression'))?></span><span><?=e(t('À confirmer'))?></span><span><?=e(t('Encouragements'))?></span><span></span></div><?php foreach($students as $s): $pct=$s['total']?round($s['done']/$s['total']*100):0; ?><a class="student-row" href="<?=route('student-detail',['enrollment'=>$s['enrollment_id']])?>"><span class="student-name"><i class="avatar" style="--avatar:<?=e($s['color'])?>"><?=e($s['initials'])?></i><b><?=e($s['name'])?></b></span><span class="row-progress"><i><em style="width:<?=$pct?>%"></em></i><b><?=$s['done']?>/<?=$s['total']?></b></span><span class="waiting-count <?=$s['waiting']?'has-waiting':''?>"><?=$s['waiting']?></span><span>✦ <?=$s['points']?></span><strong>›</strong></a><?php endforeach; ?></div></section><?php
}

