function view_students(): void
{
    $teacher=require_actor();
    purge_expired_registrations();
    $courses=all("SELECT c.*,(SELECT COUNT(*) FROM enrollments e JOIN users s ON s.id=e.student_id WHERE e.course_id=c.id AND e.status='active' AND s.account_status='active') AS student_count FROM courses c WHERE c.teacher_id=? AND c.archived=0 ORDER BY c.title",[$teacher['id']]);
    $students=all('SELECT u.*,COUNT(DISTINCT e.id) AS course_count,GROUP_CONCAT(DISTINCT c.title) AS course_titles FROM users u LEFT JOIN enrollments e ON e.student_id=u.id LEFT JOIN courses c ON c.id=e.course_id AND c.teacher_id=? WHERE u.role=? AND (u.managed_by=? OR EXISTS(SELECT 1 FROM enrollments oe JOIN courses oc ON oc.id=oe.course_id WHERE oe.student_id=u.id AND oc.teacher_id=?)) GROUP BY u.id ORDER BY u.account_status,u.class_group,u.last_name,u.first_name',[$teacher['id'],'student',$teacher['id'],$teacher['id']]);
    $selectedCourse=(int)($_GET['course']??($courses[0]['id']??0));
    $inviteCourse=null;foreach($courses as $candidate)if((int)$candidate['id']===$selectedCourse)$inviteCourse=$candidate;$inviteCourse??=$courses[0]??null;
    $inviteUrl=$inviteCourse?course_invitation_url((string)$inviteCourse['code']):'';
    ?>
