l><p class="muted-copy mb-0"><?=e(t('Un élève connecté rejoint directement le parcours ; un nouvel élève crée d’abord son compte et valide son courriel.'))?></p></section></aside><?php endif; ?></div>
    <?php render_students_action_modals($courses,$students,$selectedCourse);
