function render_student_management(array $student): void
{
    $teacher=require_actor();
    $enrollments=all('SELECT e.id,e.status,e.archived_at,c.title FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.student_id=? AND c.teacher_id=? ORDER BY c.title',[$student['id'],$teacher['id']]);
    $otherCount=(int)(one('SELECT COUNT(*) AS n FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.student_id=? AND c.teacher_id<>?',[$student['id'],$teacher['id']])['n']??0);
    $canManageAccount=(int)($student['managed_by']??0)===(int)$teacher['id']||($enrollments&&$otherCount===0);
    $canValidate=(int)($student['managed_by']??0)===(int)$teacher['id']||(bool)$enrollments;
    $labels=['active'=>t('Actif'),'pending'=>t('Courriel à valider'),'archived'=>t('Compte archivé')];
    ?><details class="student-management"><summary><span class="status <?=$student['account_status']==='active'?'ready':'draft'?>"><?=e($labels[$student['account_status']]??$student['account_status'])?></span><span><?=e(t('Gérer'))?></span></summary><div class="management-body"><h3><?=e(t('Participations'))?></h3><?php if(!$enrollments): ?><p class="muted-copy"><?=e(t('Aucune participation à vos cours.'))?></p><?php endif; ?><?php foreach($enrollments as $enrollment): ?><div class="management-row"><div><b><?=e($enrollment['title'])?></b><small><?=e(t($enrollment['status']==='active'?'Participation active':'Participation archivée'))?></small></div><div class="management-actions"><?php if($enrollment['status']==='active'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="manage_enrollment"><input type="hidden" name="enrollment_id" value="<?=$enrollment['id']?>"><input type="hidden" name="operation" value="archive"><button class="btn btn-sm btn-outline-secondary"><?=e(t('Archiver'))?></button></form><?php else: ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="manage_enrollment"><input type="hidden" name="enrollment_id" value="<?=$enrollment['id']?>"><input type="hidden" name="operation" value="reactivate"><button class="btn btn-sm btn-outline-primary"><?=e(t('Réactiver'))?></button></form><?php endif; ?><form method="post" onsubmit="return confirm('<?=e(t('Retirer définitivement cet élève du cours et supprimer sa progression associée ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="manage_enrollment"><input type="hidden" name="enrollment_id" value="<?=$enrollment['id']?>"><input type="hidden" name="operation" value="delete"><button class="btn btn-sm btn-outline-danger"><?=e(t('Retirer définitivement'))?></button></form></div></div><?php endforeach; ?><hr><h3><?=e(t('Compte élève'))?></h3><?php if($student['account_status']==='pending'&&$canValidate): ?><form method="post" class="mb-3" onsubmit="return confirm('<?=e(t('Valider le courriel de cet élève à sa place et activer son compte ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="validate_student_email"><input type="hidden" name="student_id" value="<?=$student['id']?>"><button class="btn btn-sm btn-primary"><i class="bi bi-envelope-check me-1"></i><?=e(t('Valider le courriel et activer'))?></button></form><?php endif; ?><?php if($otherCount): ?><p class="alert alert-light border small"><?=e(t('Ce compte participe aussi à un cours d’un autre enseignant : son archivage ou sa suppression globale est désactivé.'))?></p><?php elseif($canManageAccount): ?><div class="management-actions"><?php if($student['account_status']==='active'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="manage_student_account"><input type="hidden" name="student_id" value="<?=$student['id']?>"><input type="hidden" name="operation" value="archive"><button class="btn btn-sm btn-outline-secondary"><?=e(t('Archiver le compte'))?></button></form><?php elseif($student['account_status']==='archived'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="manage_student_account"><input type="hidden" name="student_id" value="<?=$student['id']?>"><input type="hidden" name="operation" value="reactivate"><button class="btn btn-sm btn-outline-primary"><?=e(t('Réactiver le compte'))?></button></form><?php endif; ?><form method="post" onsubmit="return confirm('<?=e(t('Effacer définitivement ce compte élève, toutes ses participations, progressions et encouragements ? Cette action est irréversible.'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="manage_student_account"><input type="hidden" name="student_id" value="<?=$student['id']?>"><input type="hidden" name="operation" value="delete"><button class="btn btn-sm btn-danger"><?=e(t('Effacer définitivement'))?></button></form></div><?php else: ?><p class="muted-copy"><?=e(t('Ce compte est géré par un autre enseignant.'))?></p><?php endif; ?></div></details><?php
}

function view_student_detail(): void
{
    $teacherId=(int)actor()['id'];
    $e=one("SELECT e.*,u.name,u.email,u.initials,u.color,c.title AS course_title,c.id AS course_id
        FROM enrollments e JOIN users u ON u.id=e.student_id JOIN courses c ON c.id=e.course_id
        WHERE e.id=? AND e.status='active' AND u.account_status='active'",
        [(int)($_GET['enrollment']??0)]);
    if(!$e||!teacher_can_access_course(db(),(int)$e['course_id'],$teacherId)){?><div class="empty"><?=e(t('Élève introuvable.'))?></div><?php return;}

    $items=all("SELECT pi.*,p.title,pr.student_level,pr.student_note,pr.student_validated_at,
        pr.teacher_level,pr.teacher_note,pr.teacher_validated_at,
        (SELECT MAX(lv.last_seen_at) FROM learning_visits lv
         WHERE lv.student_id=? AND lv.pathway_item_id=pi.id
           AND lv.last_seen_at>=datetime('now','-1 month')) AS last_visit_at
        FROM pathway_items pi JOIN pages p ON p.id=pi.page_id
        LEFT JOIN progress pr ON pr.pathway_item_id=pi.id AND pr.enrollment_id=?
        WHERE pi.course_id=? AND (pi.access_mode='all'
          OR (pi.access_mode='restricted' AND EXISTS(SELECT 1 FROM pathway_item_students a WHERE a.pathway_item_id=pi.id AND a.student_id=?))) ORDER BY pi.position",
        [$e['student_id'],$e['id'],$e['course_id'],$e['student_id']]);
    $activity=learning_activity_report(db(),(int)$e['id'],$teacherId);
    $rewards=reward_summary((int)$e['id']);
    $types=all('SELECT * FROM reward_types WHERE course_id=? AND active=1 ORDER BY name',[$e['course_id']]);
    $modalId='activity-history-'.(int)$e['id'];
    ?>
    <a class="back" href="<?=route('teacher',['course'=>$e['course_id']])?>">← <?=e(t('Retour au groupe'))?></a>
    <section class="student-profile">
      <span class="avatar large" style="--avatar:<?=e($e['color'])?>"><?=e($e['initials'])?></span>
      <div class="student-profile-identity"><p class="eyebrow"><?=e($e['course_title'])?></p><h1><?=e($e['name'])?></h1><p><?=e($e['email'])?></p></div>
      <div class="student-profile-actions">
        <button class="btn btn-outline-secondary" type="button" data-bs-toggle="modal" data-bs-target="#<?=$modalId?>">
          <i class="bi bi-clock-history"></i> <?=e(t('Historique des visites'))?>
        </button>
        <div class="student-score"><b>✦ <?=$rewards['total']?></b><span><?=e(t('points'))?></span></div>
      </div>
    </section>
    <div class="detail-grid"><section><div class="review-list">
    <?php foreach($items as $item): ?>
      <article class="review-card <?= $item['student_validated_at']&&!$item['teacher_validated_at']?'needs-review':''?>">
        <header>
          <span><?=$item['position']?></span>
          <div><h3><?=e($item['title'])?></h3><small><?=date_fr($item['deadline'])?><?= $item['is_evaluation']?' · '.e(t('Évaluation')):''?></small></div>
          <div class="review-status">
            <em><?=e($item['teacher_validated_at']?t('Niv.').' '.$item['teacher_level']:t($item['student_validated_at']?'À confirmer':'À faire'))?></em>
            <small><i class="bi bi-clock-history"></i> <?=e(learning_activity_datetime_label($item['last_visit_at']))?></small>
          </div>
        </header>
        <?php if($item['student_validated_at']): ?>
          <div class="student-self"><b><?=e(t('Auto-évaluation · niveau :level',['level'=>$item['student_level']]))?></b><p><?=e($item['student_note']?:t('Aucun commentaire.'))?></p></div>
          <details <?=$item['teacher_validated_at']?'':'open'?>>
            <summary><?=e(t($item['teacher_validated_at']?'Modifier la confirmation':'Confirmer le niveau'))?></summary>
            <form method="post" class="review-form"><?=csrf_field()?>
              <input type="hidden" name="action" value="teacher_validate"><input type="hidden" name="enrollment_id" value="<?=$e['id']?>"><input type="hidden" name="item_id" value="<?=$item['id']?>">
              <?=render_level_picker('level',$item['teacher_level']===null?(int)$item['student_level']:(int)$item['teacher_level'])?>
              <label class="field"><span><?=e(t("Note / Commentaire (visible par l'apprenant)"))?></span><textarea name="note" rows="4" placeholder="<?=e(t('Votre appréciation…'))?>"><?=e($item['teacher_note'])?></textarea></label>
              <div class="reward-form"><label class="field"><span><?=e(t('Petit encouragement'))?> <em><?=e(t('facultatif'))?></em></span><select name="reward_type_id" class="reward-select"><option value=""><?=e(t('Aucun cette fois'))?></option><?php foreach($types as $type): ?><option value="<?=$type['id']?>" data-points="<?=$type['default_points']?>"><?=e($type['icon'].' '.$type['name'])?></option><?php endforeach; ?></select></label><label class="field points"><span><?=e(t('Points'))?></span><input type="number" name="points" min="1" max="100" value="5"></label><label class="field reward-message"><span><?=e(t('Pourquoi ?'))?></span><input name="reward_message" placeholder="<?=e(t('Un encouragement concret'))?>"></label></div>
              <button class="button primary"><?=e(t('Confirmer'))?></button>
            </form>
          </details>
        <?php endif; ?>
      </article>
    <?php endforeach; ?>
    </div></section><aside>
      <h2><?=e(t('Acquis confirmés'))?></h2>
      <?php foreach(framework_progress((int)$e['course_id'],(int)$e['id'],'skill') as $skill): ?><div class="mini-mastery"><span><?=e($skill['code'])?> · <?=e($skill['title'])?></span><i><em style="width:<?=level_percent($skill['teacher_level']===null?null:(float)$skill['teacher_level'])?>%"></em></i><small><?=level_label($skill['teacher_level']===null?null:(int)round($skill['teacher_level']))?></small></div><?php endforeach; ?>
      <h2><?=e(t('Derniers encouragements'))?></h2>
      <?php foreach($rewards['recent'] as $reward): ?><div class="mini-reward"><span><?=e($reward['icon'])?></span><div><b><?=e($reward['name'])?> · +<?=$reward['points']?></b><small><?=e($reward['message'])?></small></div></div><?php endforeach; ?>
    </aside></div>

    <div class="modal fade activity-modal" id="<?=$modalId?>" tabindex="-1" aria-labelledby="<?=$modalId?>-title" aria-hidden="true">
      <div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content">
        <div class="modal-header"><div><p class="eyebrow mb-1"><?=e(t('30 derniers jours'))?></p><h2 class="modal-title fs-4" id="<?=$modalId?>-title"><?=e(t('Visites de :name',['name'=>$e['name']]))?></h2></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="<?=e(t('Fermer'))?>"></button></div>
        <div class="modal-body">
          <p class="activity-retention"><i class="bi bi-shield-check"></i> <?=e(t('La durée correspond au temps actif dans un onglet visible. Ces données sont automatiquement effacées après un mois.'))?></p>
          <?php if($activity): ?><div class="table-responsive"><table class="table activity-table align-middle">
            <thead><tr><th><?=e(t('Jour'))?></th><th><?=e(t('Page'))?></th><th><?=e(t('Première visite'))?></th><th><?=e(t('Dernière activité'))?></th><th><?=e(t('Sessions'))?></th><th><?=e(t('Temps actif'))?></th></tr></thead>
            <tbody><?php foreach($activity as $row): ?><tr><td><b><?=e($row['day_label'])?></b></td><td><span><?=e(t('Étape :number',['number'=>$row['position']]))?></span><strong><?=e($row['title'])?></strong></td><td><?=learning_activity_time_label($row['first_at'])?></td><td><?=learning_activity_time_label($row['last_at'])?></td><td><?=$row['sessions']?></td><td><b><?=e(learning_activity_duration_label($row['duration_seconds']))?></b></td></tr><?php endforeach; ?></tbody>
          </table></div><?php else: ?><div class="empty"><?=e(t('Aucune page consultée au cours des 30 derniers jours.'))?></div><?php endif; ?>
        </div>
      </div></div>
    </div>
    <?php
}

