cultatif</em></span><select name="reward_type_id" class="reward-select"><option value="">Aucun cette fois</option><?php foreach($types as $t): ?><option value="<?=$t['id']?>" data-points="<?=$t['default_points']?>"><?=e($t['icon'].' '.$t['name'])?></option><?php endforeach; ?></select></label><label class="field points"><span>Points</span><input type="number" name="points" min="1" max="100" value="5"></label><label class="field reward-message"><span>Pourquoi ?</span><input name="reward_message" placeholder="Un encouragement concret"></label></div><button class="button primary">Confirmer</button></form></details><?php endif; ?></article><?php endforeach; ?></div></section><aside><h2>Acquis confirmés</h2><?php foreach(framework_progress((int)$e['course_id'],(int)$e['id'],'skill') as $skill): ?><div class="mini-mastery"><span><?=e($skill['code'])?> · <?=e($skill['title'])?></span><i><em style="width:<?=level_percent($skill['teacher_level']===null?null:(float)$skill['teacher_level'])?>%"></em></i><small><?=level_label($skill['teacher_level']===null?null:(int)round($skill['teacher_level']))?></small></div><?php endforeach; ?><h2>Derniers encouragements</h2><?php foreach($rewards['recent'] as $r): ?><div class="mini-reward"><span><?=e($r['icon'])?></span><div><b><?=e($r['name'])?> · +<?=$r['points']?></b><small><?=e($r['message'])?></small></div></div><?php endforeach; ?></aside></div><?php
