function view_library(): void
{
    $teacherId=(int)actor()['id'];
    $pages=all('SELECT p.*,u.name AS owner_name,(p.owner_id=?) AS is_owner,(SELECT COUNT(*) FROM pathway_items pi WHERE pi.page_id=p.id) AS usages,(SELECT COUNT(*) FROM page_blocks b WHERE b.page_id=p.id) AS blocks FROM pages p JOIN users u ON u.id=p.owner_id WHERE p.owner_id=? OR EXISTS(SELECT 1 FROM pathway_items pi JOIN courses c ON c.id=pi.course_id WHERE pi.page_id=p.id AND (c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?))) ORDER BY p.updated_at DESC,p.title',[$teacherId,$teacherId,$teacherId,$teacherId]);
    $tags=all('SELECT DISTINCT t.* FROM tags t JOIN page_tags pt ON pt.tag_id=t.id WHERE pt.page_id IN (SELECT p.id FROM pages p WHERE p.owner_id=? OR EXISTS(SELECT 1 FROM pathway_items pi JOIN courses c ON c.id=pi.course_id WHERE pi.page_id=p.id AND (c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?)))) ORDER BY t.name',[$teacherId,$teacherId,$teacherId]);
    $objectives=all("SELECT MIN(po.id) AS id,po.title FROM page_objectives po WHERE EXISTS(SELECT 1 FROM pages p WHERE p.id=po.page_id AND (p.owner_id=? OR EXISTS(SELECT 1 FROM pathway_items pi JOIN courses c ON c.id=pi.course_id WHERE pi.page_id=p.id AND (c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?))))) GROUP BY lower(po.title) ORDER BY po.title",[$teacherId,$teacherId,$teacherId]);
    ?><section class="teacher-heading action-heading"><div class="action-heading-copy"><p class="eyebrow"><?=e(t('Atelier'))?></p><div class="action-heading-title"><h1><?=e(t('Bibliothèque de contenus'))?></h1><div class="dropdown pathway-actions-menu"><button class="btn btn-light pathway-actions-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false" aria-label="<?=e(t('Actions de la bibliothèque'))?>" title="<?=e(t('Actions de la bibliothèque'))?>"><i class="bi bi-three-dots-vertical"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="<?=route('page-edit')?>"><i class="bi bi-file-earmark-plus"></i><span><?=e(t('Nouvelle page'))?></span></a></li><li><button class="dropdown-item" type="button" data-bs-toggle="modal" data-bs-target="#library-import-modal"><i class="bi bi-box-arrow-in-down"></i><span><?=e(t('Importer une page JSON'))?></span></button></li></ul></div></div><p><?=e(t('Préparez aujourd’hui, utilisez dans un parcours quand vous le souhaitez.'))?></p></div></section>
    <div class="library-tools" data-library-filters>
      <label class="library-search">⌕ <input type="search" data-page-search placeholder="<?=e(t('Titre, texte, tag ou objectif…'))?>"></label>
      <select data-page-status aria-label="<?=e(t('Filtrer par statut'))?>"><option value=""><?=e(t('Tous les statuts'))?></option><option value="ready"><?=e(t('Prêt'))?></option><option value="draft"><?=e(t('Brouillon'))?></option></select>
      <select data-page-tag aria-label="<?=e(t('Filtrer par tag'))?>"><option value=""><?=e(t('Tous les tags'))?></option><?php foreach($tags as $tag): ?><option value="<?=$tag['id']?>"><?=e($tag['name'])?></option><?php endforeach; ?></select>
      <select data-page-objective aria-label="<?=e(t('Filtrer par objectif'))?>"><option value=""><?=e(t('Tous les objectifs'))?></option><?php foreach($objectives as $objective): ?><option value="<?=sha1(mb_strtolower($objective['title'],'UTF-8'))?>"><?=e($objective['title'])?></option><?php endforeach; ?></select>
      <span data-page-count><?=e(t(':count page(s)',['count'=>count($pages)]))?></span>
    </div><div class="page-grid"><?php foreach($pages as $p):
      $pageTags=tags_for_page((int)$p['id']);
      $pageObjectives=page_objectives(db(),(int)$p['id']);
      $search=mb_strtolower($p['title'].' '.$p['summary'].' '.implode(' ',array_column($pageTags,'name')).' '.implode(' ',array_column($pageObjectives,'title')),'UTF-8');
      ?><a class="page-card" data-page-card data-search="<?=e($search)?>" data-status="<?=e($p['status'])?>" data-tags=" <?=e(implode(' ',array_column($pageTags,'id')))?> " data-objectives=" <?=e(implode(' ',array_map(static fn(array $objective):string=>sha1(mb_strtolower($objective['title'],'UTF-8')),$pageObjectives)))?> " href="<?=route('page-edit',['id'=>$p['id']])?>"><div class="page-card-top"><span class="status <?=$p['status']?>"><?=e(t($p['status']==='ready'?'Prêt':'Brouillon'))?></span><em><?=$p['estimated_minutes']?> min</em></div><h2><?=e($p['title'])?></h2><p><?=e($p['summary'])?></p><div class="chips"><?php foreach($pageTags as $tag): ?><span style="--tag:<?=e($tag['color'])?>"><?=e($tag['name'])?></span><?php endforeach; ?></div><?php if($pageObjectives): ?><div class="page-objectives"><?php foreach($pageObjectives as $objective): ?><small>◎ <?=e($objective['title'])?></small><?php endforeach; ?></div><?php endif; ?><footer><span><?=e(t(':count blocs',['count'=>$p['blocks']]))?></span><span><?=e($p['usages']?t(':count parcours',['count'=>$p['usages']]):t('Hors parcours'))?></span><b><?=e(t('Modifier'))?> →</b></footer></a><?php endforeach; ?></div>
    <div class="empty" data-library-empty hidden><?=e(t('Aucune page ne correspond à ces filtres.'))?></div><?php render_library_import_modal();
}

function render_collaboration_comments(string $type,int $subjectId,bool $embedded=false): void
{
    $open=collaboration_comments(db(),$type,$subjectId,'open');$history=collaboration_comments(db(),$type,$subjectId,'resolved');$modalId='comment-history-'.$type.'-'.$subjectId;$addFormId='add-comment-'.$type.'-'.$subjectId;
    ?><section class="collaboration-comments"><div class="comment-heading"><h2><?=e(t('Commentaires'))?></h2><button type="button" class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#<?=$modalId?>"><i class="bi bi-clock-history"></i> <?=e(t('Historique'))?><?php if($history): ?> · <?=count($history)?><?php endif; ?></button></div>
      <?php foreach($open as $comment): $resolveFormId='resolve-comment-'.$comment['id']; ?><article class="collaboration-comment"><header><b><?=e(collaboration_person_label($comment))?></b><small><?=e(date_fr($comment['created_at'],true))?></small></header><p><?=nl2br(e($comment['body']))?></p><?php if($embedded): ?><button form="<?=$resolveFormId?>" class="btn btn-sm btn-outline-success">✓ <?=e(t('Marquer comme traité'))?></button><?php else: ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="resolve_collaboration_comment"><input type="hidden" name="comment_id" value="<?=$comment['id']?>"><button class="btn btn-sm btn-outline-success">✓ <?=e(t('Marquer comme traité'))?></button></form><?php endif; ?></article><?php endforeach; ?>
      <?php if(!$open): ?><p class="muted-copy"><?=e(t('Aucun commentaire en attente.'))?></p><?php endif; ?>
      <?php if($embedded): ?><div class="comment-form"><label class="field"><span><?=e(t('Ajouter un commentaire'))?></span><textarea form="<?=$addFormId?>" name="body" rows="3" maxlength="3000" required placeholder="<?=e(t('Décrivez précisément le point à traiter…'))?>"></textarea></label><button form="<?=$addFormId?>" class="button secondary"><?=e(t('Publier'))?></button></div><?php else: ?><form method="post" class="comment-form"><?=csrf_field()?><input type="hidden" name="action" value="add_collaboration_comment"><input type="hidden" name="subject_type" value="<?=e($type)?>"><input type="hidden" name="subject_id" value="<?=$subjectId?>"><label class="field"><span><?=e(t('Ajouter un commentaire'))?></span><textarea name="body" rows="3" maxlength="3000" required placeholder="<?=e(t('Décrivez précisément le point à traiter…'))?>"></textarea></label><button class="button secondary"><?=e(t('Publier'))?></button></form><?php endif; ?>
    </section><div class="modal fade" id="<?=$modalId?>" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-4"><?=e(t('Historique des commentaires'))?></h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="<?=e(t('Fermer'))?>"></button></div><div class="modal-body comment-history"><?php foreach($history as $comment): ?><article><header><b><?=e(collaboration_person_label($comment))?></b><small><?=e(date_fr($comment['created_at'],true))?></small></header><p><?=nl2br(e($comment['body']))?></p><footer>✓ <?=e(t('Traité par :name le :date',['name'=>collaboration_person_label($comment,'resolver'),'date'=>date_fr($comment['resolved_at'],true)]))?></footer></article><?php endforeach; ?><?php if(!$history): ?><div class="empty"><?=e(t('Aucun commentaire traité.'))?></div><?php endif; ?></div></div></div></div><?php
}

function render_embedded_comment_forms(string $type,int $subjectId): void
{
    ?><form hidden method="post" id="add-comment-<?=$type?>-<?=$subjectId?>"><?=csrf_field()?><input type="hidden" name="action" value="add_collaboration_comment"><input type="hidden" name="subject_type" value="<?=e($type)?>"><input type="hidden" name="subject_id" value="<?=$subjectId?>"></form><?php
