      <div class="editor-layout"><section><div id="blocks" class="blocks-editor"><?php foreach($blocks as $index=>$block)render_block_editor((int)$index,$block); ?></div><button type="button" class="button add-block" data-add-block>＋ <?=e(t('Ajouter un bloc'))?></button></section><div class="editor-side-column"><div class="editor-actions editor-save-dock"><select name="status" aria-label="<?=e(t('Statut'))?>"><option value="draft" <?=($page['status']??'')==='draft'?'selected':''?>><?=e(t('Brouillon'))?></option><option value="ready" <?=($page['status']??'')==='ready'?'selected':''?>><?=e(t('Prêt à utiliser'))?></option></select><button class="button primary"><i class="bi bi-check2 me-1"></i><?=e(t('Enregistrer'))?></button></div><aside class="settings-card" <?=$id?'data-edit-lock data-lock-type="page_metadata" data-lock-id="'.$id.'"':''?>><h2><?=e(t('Réglages'))?></h2><span class="edit-lock-status" data-lock-status></span><button type="button" class="release-edit-lock btn btn-sm btn-outline-secondary" data-release-edit-lock hidden><i class="bi bi-unlock"></i> <?=e(t('Libérer la zone'))?></button><label class="field"><span><?=e(t('Durée estimée'))?></span><div class="input-suffix"><input type="number" name="estimated_minutes" min="1" value="<?=e($page['estimated_minutes']??15)?>"><span>min</span></div></label><section class="page-objectives-editor"><h2><?=e(t('Objectifs visés par cette page'))?></h2><p class="muted-copy"><?=e(t('Ils seront repris automatiquement dans chaque parcours qui utilise cette page.'))?></p><div data-page-objectives><?php foreach($pageObjectives as $objective)render_page_objective_editor($objective); ?></div><button type="button" class="button secondary objective-add" data-add-page-objective>＋ <?=e(t('Ajouter un objectif'))?></button></section><fieldset><legend><?=e(t('Catégories'))?></legend><?php foreach($tags as $tag): ?><label class="check"><input type="checkbox" name="tags[]" value="<?=$tag['id']?>" <?=in_array((int)$tag['id'],$selected,true)?'checked':''?>><span style="--tag:<?=e($tag['color'])?>"><?=e($tag['name'])?></span></label><?php endforeach; ?></fieldset><?php if($page): $uses=all('SELECT c.title,pi.position FROM pathway_items pi JOIN courses c ON c.id=pi.course_id WHERE pi.page_id=?',[$id]); ?><h2><?=e(t('Utilisation'))?></h2><?php if($uses): foreach($uses as $use): ?><p class="usage">↝ <?=e($use['title'])?> · <?=e(t('étape :number',['number'=>$use['position']]))?></p><?php endforeach; else: ?><p class="muted-copy"><?=e(t('Cette page est prête dans la bibliothèque, sans être visible dans un parcours.'))?></p><?php endif; endif; ?></aside><?php if($page)render_collaboration_comments('page',$id,true); ?></div></div>
