function view_pathway_legacy(): void
{
    [$courses,$course]=teacher_context(); if(!$course)return; $items=all('SELECT pi.*,p.title,p.status,p.estimated_minutes FROM pathway_items pi JOIN pages p ON p.id=pi.page_id WHERE pi.course_id=? ORDER BY pi.position',[$course['id']]); $pages=all('SELECT * FROM pages WHERE status=? ORDER BY title',['ready']); $objectives=all('SELECT * FROM course_objectives WHERE course_id=? ORDER BY position',[$course['id']]); $skills=all('SELECT * FROM course_skills WHERE course_id=? ORDER BY position',[$course['id']]); $rewards=all('SELECT * FROM reward_types WHERE course_id=? ORDER BY name',[$course['id']]);
    ?><section class="teacher-heading"><div><p class="eyebrow">Conception pédagogique</p><h1>Parcours & référentiel</h1><p>Seul l’enseignant voit et modifie cette organisation.</p></div></section><div class="course-tabs compact"><?php foreach($courses as $c): ?><a class="<?=$c['id']===$course['id']?'active':''?>" href="<?=route('pathway',['course'=>$c['id']])?>"><i style="--course:<?=e($c['accent'])?>"></i><?=e($c['title'])?></a><?php endforeach; ?></div><div class="pathway-layout"><section><div class="pathway-list"><?php foreach($items as $item): $edit=(int)($_GET['edit']??0)===$item['id']; ?><article class="pathway-row"><span class="position"><?=$item['position']?></span><div><b><?=e($item['title'])?></b><small><?=date_fr($item['deadline'])?> · <?=$item['estimated_minutes']?> min<?= $item['is_evaluation']?' · Évaluation':''?></small><div class="chips"><?php foreach(all('SELECT s.code FROM course_skills s JOIN item_skills l ON l.skill_id=s.id WHERE l.pathway_item_id=?',[$item['id']]) as $s): ?><span class="skill"><?=e($s['code'])?></span><?php endforeach; ?></div></div><div class="row-actions"><form method="post"><input type="hidden" name="action" value="move_item"><input type="hidden" name="item_id" value="<?=$item['id']?>"><button name="direction" value="up" aria-label="Monter">↑</button><button name="direction" value="down" aria-label="Descendre">↓</button></form><a href="<?=route('pathway',['course'=>$course['id'],'edit'=>$item['id']])?>">Régler</a></div></article><?php if($edit): $oi=array_column(all('SELECT objective_id FROM item_objectives WHERE pathway_item_id=?',[$item['id']]),'objective_id');$si=array_column(all('SELECT skill_id FROM item_skills WHERE pathway_item_id=?',[$item['id']]),'skill_id'); ?><form method="post" class="item-settings"><input type="hidden" name="action" value="update_pathway_item"><input type="hidden" name="item_id" value="<?=$item['id']?>"><label class="field"><span>Échéance</span><input type="date" name="deadline" value="<?=e($item['deadline'])?>"></label><label class="check plain"><input type="checkbox" name="is_evaluation" <?=$item['is_evaluation']?'checked':''?>> Cette étape est une évaluation</label><label class="field"><span>Consigne propre à ce cours</span><textarea name="instructions" rows="2"><?=e($item['instructions'])?></textarea></label><fieldset><legend>Objectifs travaillés</legend><?php foreach($objectives as $o): ?><label class="check plain"><input type="checkbox" name="objectives[]" value="<?=$o['id']?>" <?=in_array($o['id'],$oi)?'checked':''?>> <?=e($o['title'])?></label><?php endforeach; ?></fieldset><fieldset><legend>Compétences mobilisées</legend><?php foreach($skills as $s): ?><label class="check plain"><input type="checkbox" name="skills[]" value="<?=$s['id']?>" <?=in_array($s['id'],$si)?'checked':''?>> <?=e($s['code'].' · '.$s['title'])?></label><?php endforeach; ?></fieldset><button class="button primary">Mettre à jour l’étape</button></form><?php endif; endforeach; ?></div><details class="add-panel"><summary>＋ Ajouter une page au parcours</summary><form method="post"><input type="hidden" name="action" value="add_pathway_item"><input type="hidden" name="course_id" value="<?=$course['id']?>"><label class="field"><span>Page</span><select name="page_id"><?php foreach($pages as $p): ?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach; ?></select></label><label class="field"><span>Échéance</span><input type="date" name="deadline"></label><label class="check plain"><input type="checkbox" name="is_evaluation"> Évaluation</label><button class="button primary">Ajouter à la fin</button></form></details></section><aside class="framework-panel"><h2>Objectifs du cours</h2><?php foreach($objectives as $o): ?><div class="framework-item"><span>◎</span><div><b><?=e($o['title'])?></b><small><?=e($o['description'])?></small></div></div><?php endforeach; ?><details><summary>＋ Ajouter un objectif</summary><form method="post"><input type="hidden" name="action" value="add_framework"><input type="hidden" name="kind" value="objective"><input type="hidden" name="course_id" value="<?=$course['id']?>"><input name="title" required placeholder="Titre"><textarea name="description" placeholder="Description"></textarea><button class="button secondary">Ajouter</button></form></details><h2>Compétences</h2><?php foreach($skills as $s): ?><div class="framework-item"><span><?=e($s['code'])?></span><div><b><?=e($s['title'])?></b><small><?=e($s['description'])?></small></div></div><?php endforeach; ?><details><summary>＋ Ajouter une compétence</summary><form method="post"><input type="hidden" name="action" value="add_framework"><input type="hidden" name="kind" value="skill"><input type="hidden" name="course_id" value="<?=$course['id']?>"><input name="code" required placeholder="Code court"><input name="title" required placeholder="Titre"><textarea name="description" placeholder="Description"></textarea><button class="button secondary">Ajouter</button></form></details><h2>Types d’encouragements</h2><div class="reward-config"><?php foreach($rewards as $r): ?><span><?=e($r['icon'])?> <?=e($r['name'])?> <b>+<?=$r['default_points']?></b></span><?php endforeach; ?></div><details><summary>＋ Nouvel encouragement</summary><form method="post"><input type="hidden" name="action" value="add_reward_type"><input type="hidden" name="course_id" value="<?=$course['id']?>"><div class="inline-fields"><input name="icon" value="✨" aria-label="Icône"><input name="name" required placeholder="Nom"></div><input type="number" name="default_points" min="1" value="5"><button class="button secondary">Ajouter</button></form></details></aside></div><?php
