function view_pathway(): void
{
    $teacherId=(int)actor()['id'];
    [$courses,$course]=teacher_context();
    $archived=all('SELECT * FROM courses WHERE teacher_id=? AND archived=1 ORDER BY title',[$teacherId]);
    ?><section class="teacher-heading"><div><p class="eyebrow"><?=e(t('Conception pédagogique'))?></p><h1><?=e(t('Parcours & référentiel'))?></h1><p><?=e(t('Organisez les étapes, archivez un ancien parcours ou repartez d’une copie.'))?></p></div><div class="dropdown pathway-actions-menu"><button class="btn btn-light pathway-actions-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false" aria-label="<?=e(t('Actions des parcours'))?>" title="<?=e(t('Actions des parcours'))?>"><i class="bi bi-three-dots-vertical"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item" type="button" data-bs-toggle="modal" data-bs-target="#pathway-create-modal"><i class="bi bi-plus-circle"></i><span><?=e(t('Nouveau parcours'))?></span></button></li><li><button class="dropdown-item" type="button" data-bs-toggle="modal" data-bs-target="#pathway-import-modal"><i class="bi bi-box-arrow-in-down"></i><span><?=e(t('Importer un parcours'))?></span></button></li></ul></div></section><?php
    if(!$course){?><section class="course-management"><div class="course-management-copy"><p class="eyebrow"><?=e(t('Gestion du parcours'))?></p><div class="course-management-title"><h2><?=e(t('Aucun parcours actif.'))?></h2></div><p><?=e(t('Vous pouvez réactiver ou copier un parcours archivé ci-dessous.'))?></p></div></section><?php render_pathway_action_modals(null,false);render_archived_courses($archived); return;}

    $isOwner=(int)$course['teacher_id']===$teacherId;$members=course_teachers(db(),(int)$course['id']);
    $candidates=$isOwner?all("SELECT id,name,email FROM users WHERE role='teacher' AND account_status='active' AND id<>? AND id NOT IN (SELECT teacher_id FROM course_teachers WHERE course_id=?) ORDER BY name",[$teacherId,$course['id']]):[];
    $courseStudents=all("SELECT u.id,u.name,u.initials FROM enrollments e JOIN users u ON u.id=e.student_id WHERE e.course_id=? AND e.status='active' AND u.account_status='active' ORDER BY u.name",[$course['id']]);
    $items=all('SELECT pi.*,p.title,p.status,p.estimated_minutes FROM pathway_items pi JOIN pages p ON p.id=pi.page_id WHERE pi.course_id=? ORDER BY pi.position',[$course['id']]);
    $tagsByItem=[];foreach(all('SELECT pi.id AS item_id,t.name,t.color FROM pathway_items pi JOIN page_tags pt ON pt.page_id=pi.page_id JOIN tags t ON t.id=pt.tag_id WHERE pi.course_id=? ORDER BY t.name',[$course['id']]) as $tag)$tagsByItem[(int)$tag['item_id']][]=$tag;
    $pages=all("SELECT p.* FROM pages p WHERE p.status='ready' AND (p.owner_id=? OR EXISTS(SELECT 1 FROM pathway_items x JOIN courses c ON c.id=x.course_id WHERE x.page_id=p.id AND (c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?)))) ORDER BY p.title",[$teacherId,$teacherId,$teacherId]);
    $objectives=pathway_objectives(db(),(int)$course['id']);
    $skills=all('SELECT * FROM course_skills WHERE course_id=? ORDER BY position',[$course['id']]);
    $sidebarSkills=pathway_sidebar_skills(db(),(int)$course['id']);
    $rewards=all('SELECT * FROM reward_types WHERE course_id=? AND active=1 ORDER BY name',[$course['id']]);
    ?><div class="course-tabs compact"><?php foreach($courses as $candidate): ?><a class="<?=$candidate['id']===$course['id']?'active':''?>" href="<?=route('pathway',['course'=>$candidate['id']])?>"><i style="--course:<?=e($candidate['accent'])?>"></i><?=e($candidate['title'])?></a><?php endforeach; ?></div>
