      <form method="post" class="item-settings" data-edit-lock data-lock-type="pathway_item" data-lock-id="<?=$item['id']?>">
        <?=csrf_field()?><input type="hidden" name="action" value="update_pathway_item"><input type="hidden" name="item_id" value="<?=$item['id']?>"><input type="hidden" name="item_revision" value="<?=$item['revision']?>">
        <span class="edit-lock-status" data-lock-status></span><button type="button" class="release-edit-lock btn btn-sm btn-outline-secondary" data-release-edit-lock hidden><i class="bi bi-unlock"></i> <?=e(t('Libérer la zone'))?></button>
