        <details class="student-access"><summary><?=e(t('Accès à cette étape'))?></summary><div class="student-access-body">
          <label class="check plain"><input type="radio" name="access_mode" value="all" <?=$accessMode==='all'?'checked':''?>> <?=e(t('Tous les élèves inscrits'))?></label>
          <label class="check plain"><input type="radio" name="access_mode" value="restricted" <?=$accessMode==='restricted'?'checked':''?>> <?=e(t('Seulement les élèves sélectionnés'))?></label>
