          <div class="allowed-students" data-allowed-students><?php foreach($courseStudents as $student): ?><label class="check plain"><input type="checkbox" name="allowed_students[]" value="<?=$student['id']?>" <?=in_array((int)$student['id'],$allowedStudents,true)?'checked':''?>><span class="avatar mini"><?=e($student['initials'])?></span><?=e($student['name'])?></label><?php endforeach; ?></div>
          <small><?=e(t('Sans restriction, cette étape reste visible par tous les élèves du parcours.'))?></small>
        </div></details><button class="button primary"><?=e(t('Mettre à jour l’étape'))?></button>
      </form><?php endif; endforeach; ?></div>
      <details class="add-panel"><summary>＋ <?=e(t('Ajouter une page au parcours'))?></summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add_pathway_item"><input type="hidden" name="course_id" value="<?=$course['id']?>"><label class="field"><span><?=e(t('Page'))?></span><select name="page_id"><?php foreach($pages as $page): ?><option value="<?=$page['id']?>"><?=e($page['title'])?></option><?php endforeach; ?></select></label><label class="field"><span><?=e(t('Échéance'))?></span><input type="date" name="deadline"></label><label class="check plain"><input type="checkbox" name="is_evaluation"> <?=e(t('Évaluation'))?></label><button class="button primary" <?=$pages?'':'disabled'?>><?=e(t('Ajouter à la fin'))?></button><?php if(!$pages): ?><p class="muted-copy"><?=e(t('Aucune page prête n’est disponible dans votre bibliothèque.'))?></p><?php endif; ?></form></details>
    </section><div class="pathway-side-column"><aside class="framework-panel"><h2><?=e(t('Objectifs du parcours'))?></h2><p class="muted-copy"><?=e(t('Les objectifs du parcours sont issus automatiquement des pages qui le composent.'))?></p><?php foreach($objectives as $objective): ?><div class="framework-item"><span>◎</span><div><b><?=e($objective['title'])?></b><small><?=e($objective['description'])?></small></div></div><?php endforeach; ?><h2><?=e(t('Compétences'))?></h2><?php foreach($sidebarSkills as $skill): ?><div class="framework-item <?=$skill['access_visibility']==='restricted'?'framework-item-restricted':''?>"><span><?=e($skill['code'])?></span><div class="framework-item-content"><b><?=e($skill['title'])?></b><small><?=e($skill['description'])?></small></div><form method="post" class="framework-remove" onsubmit="return confirm('<?=e(t('Retirer cette compétence du parcours ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="remove_skill"><input type="hidden" name="skill_id" value="<?=$skill['id']?>"><button aria-label="<?=e(t('Retirer cette compétence'))?>" title="<?=e(t('Retirer cette compétence'))?>">×</button></form></div><?php endforeach; ?><details><summary>＋ <?=e(t('Ajouter une compétence'))?></summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add_framework"><input type="hidden" name="kind" value="skill"><input type="hidden" name="course_id" value="<?=$course['id']?>"><input name="code" required placeholder="<?=e(t('Code court'))?>"><input name="title" required placeholder="<?=e(t('Titre'))?>"><textarea name="description" placeholder="<?=e(t('Description'))?>"></textarea><button class="button secondary"><?=e(t('Ajouter'))?></button></form></details><h2><?=e(t('Types d’encouragements'))?></h2><div class="reward-config"><?php foreach($rewards as $reward): ?><span class="reward-type"><?=e($reward['icon'])?> <?=e($reward['name'])?> <b>+<?=$reward['default_points']?></b><form method="post" onsubmit="return confirm('<?=e(t('Retirer ce type d’encouragement du parcours ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="remove_reward_type"><input type="hidden" name="reward_type_id" value="<?=$reward['id']?>"><button aria-label="<?=e(t('Retirer ce type d’encouragement'))?>" title="<?=e(t('Retirer ce type d’encouragement'))?>">×</button></form></span><?php endforeach; ?></div><details><summary>＋ <?=e(t('Nouvel encouragement'))?></summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add_reward_type"><input type="hidden" name="course_id" value="<?=$course['id']?>"><div class="inline-fields"><input name="icon" value="✨" aria-label="<?=e(t('Icône'))?>"><input name="name" required placeholder="<?=e(t('Nom'))?>"></div><input type="number" name="default_points" min="1" value="5"><button class="button secondary"><?=e(t('Ajouter'))?></button></form></details></aside><?php render_collaboration_comments('course',(int)$course['id']); ?></div></div><?php
    render_archived_courses($archived);
}

