function view_admin(): void
{
    $admin=require_actor();
    if((int)($admin['is_superadmin']??0)!==1){?><div class="empty"><?=e(t('Accès superadmin refusé.'))?></div><?php return;}
    $release=maintenance_release_status(dirname(__DIR__));
    $users=all("SELECT u.*,(SELECT COUNT(*) FROM courses c WHERE c.teacher_id=u.id) AS course_count,(SELECT COUNT(*) FROM enrollments e WHERE e.student_id=u.id) AS enrollment_count FROM users u ORDER BY u.role DESC,u.last_name,u.first_name");
    $pages=all('SELECT p.*,u.name AS owner_name,(SELECT COUNT(*) FROM pathway_items pi WHERE pi.page_id=p.id) AS usages FROM pages p JOIN users u ON u.id=p.owner_id ORDER BY p.title');
    $courses=all('SELECT c.*,u.name AS teacher_name,(SELECT COUNT(*) FROM pathway_items pi WHERE pi.course_id=c.id) AS items,(SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) AS enrollments FROM courses c JOIN users u ON u.id=c.teacher_id ORDER BY c.archived,c.title');
    ?><section class="page-heading"><p class="eyebrow"><?=e(t('Administration globale'))?></p><h1><?=e(t('Superadministration'))?></h1><p><?=e(t('Ces suppressions sont définitives et peuvent supprimer en cascade parcours, progressions, encouragements et contenus liés.'))?></p></section>
    <section class="maintenance-card"><div class="maintenance-heading"><div><p class="eyebrow"><?=e(t('Maintenance de l’application'))?></p><h2><?=e(t('Versions et mises à jour'))?></h2></div><?php if($release['available']): ?><span class="status draft"><?=e(t('Mise à jour disponible'))?></span><?php elseif($release['current']): ?><span class="status ready"><?=e(t('À jour'))?></span><?php else: ?><span class="status"><?=e(t('État inconnu'))?></span><?php endif; ?></div>
      <div class="version-table" role="table" aria-label="<?=e(t('Versions de l’application'))?>"><div role="row"><span role="cell"><?=e(t('Version installée'))?></span><strong role="cell"><?=e($release['installed'])?></strong></div><div role="row"><span role="cell"><?=e(t('Dernière version stable disponible'))?></span><strong role="cell"><?=e($release['latest']??'—')?></strong></div><div role="row"><span role="cell"><?=e(t('Dernière vérification'))?></span><strong role="cell"><?=e(maintenance_format_checked_at((int)$release['checked_at']))?></strong></div></div>
      <?php if($release['error']): ?><p class="alert alert-warning mb-3"><i class="bi bi-wifi-off me-2"></i><?=e(t('Vérification impossible : :details',['details'=>$release['error']]))?></p><?php elseif($release['available']): ?><p class="muted-copy"><?=e(t('La mise à jour sauvegarde la base, vérifie chaque fichier, puis préserve la base et les fichiers importés.'))?></p><?php else: ?><p class="muted-copy"><?=e(t('Aucune mise à jour stable plus récente n’est disponible.'))?></p><?php endif; ?>
      <?php if(!$release['writable']): ?><p class="alert alert-danger mb-3"><?=e(t('Le serveur Web ne peut pas écrire dans le dossier de l’application. La mise à jour automatique est désactivée.'))?></p><?php endif; ?>
      <div class="maintenance-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="superadmin_check_update"><button class="btn btn-outline-secondary"><i class="bi bi-arrow-clockwise me-1"></i><?=e(t('Vérifier maintenant'))?></button></form><?php if($release['available']&&$release['latest']): ?><form method="post" onsubmit="return confirm('<?=e(t('Installer maintenant la version :version ? Une sauvegarde sera créée avant le remplacement du code.',['version'=>$release['latest']]))?>')"><?=csrf_field()?><input type="hidden" name="action" value="superadmin_apply_update"><input type="hidden" name="expected_version" value="<?=e($release['latest'])?>"><button class="btn btn-primary" <?=$release['writable']?'':'disabled'?>> <i class="bi bi-cloud-arrow-down me-1"></i><?=e(t('Mettre à jour la version actuelle avec :version',['version'=>$release['latest']]))?></button></form><?php endif; ?></div>
      <small><?=e(t('Source stable : branche main du dépôt webeLi-lms. Cette fonction est réservée au superadmin.'))?></small>
    </section>
    <div class="admin-metrics"><div><b><?=count($users)?></b><span><?=e(t('utilisateurs'))?></span></div><div><b><?=count($pages)?></b><span><?=e(t('pages'))?></span></div><div><b><?=count($courses)?></b><span><?=e(t('parcours'))?></span></div></div>
    <section class="admin-section"><h2><?=e(t('Utilisateurs'))?></h2><div class="admin-list"><?php foreach($users as $user): $self=(int)$user['id']===(int)$admin['id']; ?><article><div><b><?=e($user['first_name'].' '.$user['last_name'])?></b><small><?=e($user['email'])?> · <?=e(t($user['role']==='teacher'?'Enseignant':'Élève'))?><?= $user['is_superadmin']?' · superadmin':''?><?= $self?' · '.e(t('session actuelle')):''?></small><em><?=e($user['role']==='teacher'?t(':count parcours',['count'=>$user['course_count']]):t(':count inscription(s)',['count'=>$user['enrollment_count']]))?></em></div><form method="post" onsubmit="return confirm('<?=e(t($self?'Effacer votre propre compte superadmin et fermer cette session ?':'Effacer définitivement cet utilisateur et toutes ses données liées ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="superadmin_delete"><input type="hidden" name="entity" value="user"><input type="hidden" name="id" value="<?=$user['id']?>"><button class="btn btn-sm btn-danger"><?=e(t($self?'Effacer mon compte':'Effacer'))?></button></form></article><?php endforeach; ?></div></section>
    <section class="admin-section"><h2><?=e(t('Pages'))?></h2><div class="admin-list"><?php foreach($pages as $page): ?><article><div><b><?=e($page['title'])?></b><small><?=e($page['reference'])?> · <?=e($page['owner_name'])?></small><em><?=e(t(':count parcours',['count'=>$page['usages']]))?></em></div><form method="post" onsubmit="return confirm('<?=e(t('Effacer cette page partout, y compris ses étapes et progressions ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="superadmin_delete"><input type="hidden" name="entity" value="page"><input type="hidden" name="id" value="<?=$page['id']?>"><button class="btn btn-sm btn-danger"><?=e(t('Effacer partout'))?></button></form></article><?php endforeach; ?></div></section>
    <section class="admin-section"><h2><?=e(t('Parcours'))?></h2><div class="admin-list"><?php foreach($courses as $course): ?><article><div><b><?=e($course['title'])?></b><small><?=e($course['reference'])?> · <?=e($course['teacher_name'])?></small><em><?=e(t(':items étape(s) · :enrollments inscription(s)',['items'=>$course['items'],'enrollments'=>$course['enrollments']]))?></em></div><form method="post" onsubmit="return confirm('<?=e(t('Effacer définitivement ce parcours et toutes ses données ?'))?>')"><?=csrf_field()?><input type="hidden" name="action" value="superadmin_delete"><input type="hidden" name="entity" value="course"><input type="hidden" name="id" value="<?=$course['id']?>"><button class="btn btn-sm btn-danger"><?=e(t('Effacer'))?></button></form></article><?php endforeach; ?></div></section><?php
